mkdir -p /tmp/probe-5/rusttest && cd /tmp/probe-5/rusttest && cat > t.rs <<'EOF'
use std::path::Path;
fn main() {
    for n in ["", ".", "..", "...", "....", "sub", "mynote", "mynote.md", "mynote.MD", "a.b", "a.b.md", ".hidden", "stray.txt", "x..", "..x"] {
        let p = Path::new("/v/folder").join(n);
        println!("{:12?} join={:?} with_ext_md={:?} file_stem={:?} ext={:?} file_name={:?}",
            n, p, p.with_extension("md"), p.file_stem(), p.extension(), p.file_name());
    }
}
EOF
rustc -O t.rs -o t && ./t

cd /tmp/probe-5/rusttest && cat > t2.rs <<'EOF'
use std::path::Path;
fn main() {
    for n in ["", ".", "..", "...", "..x", "x..", "a.b", "mynote.MD", ".hidden"] {
        let p = Path::new("/v/folder").join(n);
        let w = p.with_extension("md");
        println!("name=<{}> joined=<{}> with_ext=<{}>", n, p.display(), w.display());
    }
}
EOF
rustc -O t2.rs -o t2 && ./t2

cd /tmp/probe-5/rusttest && cat > t3.rs <<'EOF'
use std::path::Path;
fn main() {
    for n in ["..x", "x..", "...", "a.b", ".."] {
        let w = Path::new(n).with_extension("md");
        println!("name=<{}> with_ext=<{}> bytes={:?}", n, w.display(), w.as_os_str().as_encoded_bytes());
    }
}
EOF
rustc -O t3.rs -o t3 && ./t3
export HOME=/tmp/probe-5 XDG_CONFIG_HOME=/tmp/probe-5/.config XDG_DATA_HOME=/tmp/probe-5/.data
